files.content:
*,
*::after,
*::before {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
}

p {
  margin: 0;
}

.question {
  background-color: #fd24af;
  color: #fff;
  padding: 20px;
}

.answer {
  background-color: #80d994;
  color: #fff;
  padding: 60px 20px;
}
